import openpyxl
wb = openpyxl.load_workbook('1_51249_answer_template_7943_input.xlsx')
ws = wb['Sheet1']
for row in ws.iter_rows(min_row=1, max_row=11, min_col=1, max_col=4):
    for c in row:
        f = c.fill
        desc = []
        try:
            desc.append('pattern='+str(f.patternType))
        except Exception as e:
            desc.append('patternErr='+str(e))
        for attr in ['fgColor','bgColor']:
            col = getattr(f, attr, None)
            try:
                desc.append(attr+' type='+str(col.type)+' rgb='+str(col.rgb)+' theme='+str(col.theme)+' tint='+str(col.tint)+' indexed='+str(col.indexed))
            except Exception as e:
                desc.append(attr+'Err='+str(e))
        print(c.coordinate, 'style=', c.style_id, ' | '.join(desc))
"

